package com.gmail.manhle240406.project.community;
import org.junit.Test;
import java.util.*;
import com.gmail.manhle240406.project.adoption.DemoShareLinks;
import static org.junit.Assert.*;
public final class CommunityIntentTest {
 private SocialCommand command(String kind,Map<String,Object> input){return new SocialCommand(kind,"11111111-1111-4111-8111-111111111111",kind.equals("add_comment")?"22222222-2222-4222-8222-222222222222":null,kind.equals("publish")?0:1,0,0,input,"33333333-3333-4333-8333-333333333333");}
 @Test public void ageAndBootNeverExtendConsent(){assertTrue(CommunityIntent.maySend(100,4,101,4,0));assertFalse(CommunityIntent.maySend(100,4,99,4,0));assertFalse(CommunityIntent.maySend(100,4,100+CommunityIntent.MAX_AGE,4,0));assertFalse(CommunityIntent.maySend(100,4,101,5,0));assertFalse(CommunityIntent.maySend(100,-1,101,-1,0));assertFalse(CommunityIntent.maySend(100,4,101,4,8));}
 @Test public void queueRejectsPrivilegedAndNonconsensualCommands(){assertThrows(IllegalArgumentException.class,()->CommunityIntent.validate(command("hide",Collections.emptyMap())));Map<String,Object> input=CommunitySchema.fields("A story",null);assertThrows(IllegalArgumentException.class,()->CommunityIntent.validate(command("publish",input)));input.put("consent",true);CommunityIntent.validate(command("publish",input));input.put("moderatorHold","clear");assertThrows(IllegalArgumentException.class,()->CommunityIntent.validate(command("publish",input)));}
 @Test public void commentsAndDesiredLikesHaveStrictInputs(){CommunityIntent.validate(command("set_like",SocialRepository.map("active",false)));assertThrows(IllegalArgumentException.class,()->CommunityIntent.validate(command("set_like",SocialRepository.map("active",true,"count",10L))));CommunityIntent.validate(command("add_comment",SocialRepository.map("body","A comment")));assertThrows(IllegalArgumentException.class,()->CommunityIntent.validate(command("add_comment",SocialRepository.map("body"," "))));}
 @Test public void audienceConsentIsExplicitAndFrozen(){Map<String,Object> input=CommunitySchema.fields("A public story",null);input.put("consent",true);input.put("audience","everyone");SocialCommand c=command("publish",input);CommunityIntent.validate(c);input.put("audience","unknown");assertEquals("everyone",c.input.get("audience"));assertThrows(IllegalArgumentException.class,()->CommunityIntent.validate(command("publish",input)));}
 @Test public void receiptMatchingAcceptsEquivalentJsonAndFirestoreNumbers(){Map<String,Object> input=CommunitySchema.fields("An adoption story",null);input.put("consent",true);input.put("audience","community");input.put("type","adoption");input.put("listingContentVersion",1L);input.put("participationConsent",SocialRepository.map("termsVersion",1L));SocialCommand c=command("publish",input);Map<String,Object> receipt=SocialRepository.map("schemaVersion",2L,"operationId",c.operationId,"command",c.command,"postId",c.postId,"targetId",null,"base",SocialRepository.map("contentVersion",0L,"controlVersion",0L,"targetVersion",0L),"input",new HashMap<>(c.input));((Map<String,Object>)receipt.get("input")).put("listingContentVersion",1);((Map<String,Object>)((Map<String,Object>)receipt.get("input")).get("participationConsent")).put("termsVersion",1);assertTrue(c.matches(receipt));}
 @Test public void demoLinksAreExplicitAndRejectPayloadInjection(){assertEquals("ANILOVE demo link - not a live page: https://anilove.example.invalid/p/post-1",DemoShareLinks.text("p","post-1"));assertThrows(IllegalArgumentException.class,()->DemoShareLinks.text("private","post-1"));for(String bad:Arrays.asList("../other","id?token=x","id%2fother","id#secret","id with spaces"))assertThrows(IllegalArgumentException.class,()->DemoShareLinks.text("l",bad));}
}
